"""Transcripción editorial reproducible. No descarga ni infiere datos personales."""
import csv
import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
DATA = ROOT / 'data'
DATE = '2026-10-22'

def save(name, value):
    (DATA / f'{name}.json').write_text(json.dumps(value, ensure_ascii=False, indent=2) + '\n')

def csv_save(name, rows):
    with (DATA / f'{name}.csv').open('w', newline='', encoding='utf-8-sig') as f:
        writer = csv.DictWriter(f, fieldnames=list(rows[0]))
        writer.writeheader()
        for r in rows:
            writer.writerow({k: json.dumps(v, ensure_ascii=False) if isinstance(v, (list, dict)) else '' if v is None else v for k,v in r.items()})

