cases=[]
def case(id,title,sid,occurred,precision,region,place,geo,channels,payments,entities,demand,paid,amount_note,stage,summary,control,limitation):
    s=next(s for s in sources if s['id']==sid)
    cases.append(dict(id=id,title=title,event_date=occurred,event_date_precision=precision,published_at=s['published_at'],region=region,location=place,geographic_precision=geo,modality='Extorsión bajo amenazas',communication_channels=channels,sim_type=None,telecom_operator=None,esim_provider=None,payment_methods=payments,entities_mentioned=entities,demanded_pen=demand,paid_pen=paid,recovered_pen=None,frozen_pen=None,seized_pen=None,controlled_payment_pen=5 if id=='C003' else None,currency='PEN',amount_note=amount_note,procedural_stage=stage,final_judgment_confirmed=False,summary=summary,account_control=control,source_ids=[sid],source_url=s['url'],evidence_locator=s['locator'],accessed_at=DATE,limitations=limitation))
